const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // A point near Nottingham on the Trent River, buffered to create a small ROI.
    const point = ee.Geometry.Point([-1.1396, 52.9548]);
    const geometry = point.buffer(5000); // 5 km buffer around the point

    const preFloodStartDate = '2017-08-15';
    const preFloodEndDate = '2017-09-14'; // Before the flood event window
    const floodStartDate = '2017-09-15';
    const floodEndDate = '2017-09-20';

    // Sentinel-1 Preprocessing Function
    function applySentinel1Processing(image) {
      return image
        .select('VH')
        .addBands(image.select('VV'))
        .focal_median(50, 'square', 'pixels', 1) // Apply median filter to reduce speckle
        .copyProperties(image, ['system:time_start']);
    }

    // 2. Data Acquisition & Check
    let preFloodCollection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(preFloodStartDate, preFloodEndDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')) // Consistent orbit pass
      .map(applySentinel1Processing);

    let floodCollection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(floodStartDate, floodEndDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')) // Consistent orbit pass
      .map(applySentinel1Processing);

    const preFloodSize = await preFloodCollection.size().getInfo();
    const floodSize = await floodCollection.size().getInfo();

    if (preFloodSize === 0) {
      console.log(`Pre-flood images (${preFloodStartDate} to ${preFloodEndDate}): 0`);
      console.log("C1");
      return;
    }
    if (floodSize === 0) {
      console.log(`Flood event images (${floodStartDate} to ${floodEndDate}): 0`);
      console.log("C1");
      return;
    }

    // Mosaic and convert to dB for analysis
    const preFloodImage = ee.Image(preFloodCollection.median()).unitScale(0, 1).rename('pre_VH').clip(geometry);
    const floodImage = ee.Image(floodCollection.median()).unitScale(0, 1).rename('flood_VH').clip(geometry);

    // Check if the images are valid after mosaicking. This can happen if median fails due to no data.
    const preFloodPixels = await preFloodImage.select('pre_VH').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e9
    }).get('pre_VH').getInfo();

    const floodPixels = await floodImage.select('flood_VH').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e9
    }).get('flood_VH').getInfo();

    if (preFloodPixels === 0 || floodPixels === 0) {
      console.log(`Pre-flood images: ${preFloodSize} (Valid Pixels: ${preFloodPixels})`);
      console.log(`Flood event images: ${floodSize} (Valid Pixels: ${floodPixels})`);
      console.log("C2");
      return;
    }

    // 3. Flood Detection Logic
    // Convert to dB, as flood detection is often done with dB values
    const preFloodImage_dB = ee.Image.constant(1).multiply(preFloodImage.log10().multiply(10)).rename('pre_VH_dB');
    const floodImage_dB = ee.Image.constant(1).multiply(floodImage.log10().multiply(10)).rename('flood_VH_dB');

    // Calculate the difference in VH backscatter. Flooding causes a decrease in backscatter.
    // So (pre_event_dB - event_dB) > 0 indicates potential flooding.
    const difference_dB = preFloodImage_dB.subtract(floodImage_dB).rename('difference_dB');

    // Threshold for detecting new water. A decrease of more than 1.5 dB is a common indicator.
    const floodThreshold = 1.5; // dB
    const floodedAreaImage = difference_dB.gt(floodThreshold).and(floodImage_dB.lt(-12)); // threshold for water (VH < -12 dB)

    // Calculate the area of detected flood pixels
    const floodAreaSqM = floodedAreaImage.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10, // Higher resolution for area calculation
      maxPixels: 1e9
    }).get('difference_dB').getInfo(); // The band name is 'difference_dB' due to previous operation

    if (floodAreaSqM === null || isNaN(floodAreaSqM)) {
      console.log("C3");
      return;
    }

    const floodAreaSqKm = floodAreaSqM / 1e6; // Convert square meters to square kilometers

    console.log(`Pre-flood images: ${preFloodSize} (Valid Pixels: ${preFloodPixels})`);
    console.log(`Flood event images: ${floodSize} (Valid Pixels: ${floodPixels})`);
    console.log(`Detected Flood Area (within 5km buffer of Trent River): ${floodAreaSqKm.toFixed(2)} km²`);

    const minFloodArea_km2 = 0.1; // Define a minimum area to consider it a flood event

    if (floodAreaSqKm > minFloodArea_km2) {
      console.log("A"); // Yes, flooding detected
    } else {
      console.log("B"); // No significant flooding detected
    }

  } catch (error) {
    console.error("Analysis failed: ", error);
    console.log("D"); // General error/failure
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
